<?php $costs = $repairCosts ?? ['ready' => false]; ?>
<section id="repair-costs" class="damage-costs" aria-labelledby="repair-costs-title">
<h2 id="repair-costs-title">Repair Costs</h2>
<?php if (! empty($costRetry)): ?><p role="status">A prior save outcome still needs verification. The original command key and frozen source identity are retained.</p><form action="<?= $base ?>/costs" method="post"><?= csrf_field() ?><button type="submit">Retry original cost command</button></form>
<?php elseif (! $costs['ready']): ?><p>Repair cost recording is unavailable until its schema is ready.</p><?php else: ?>
<?php if ($costs['invoiced'] === null): ?><p><strong>Repair cost: Unknown</strong></p><p>No repair cost recorded</p><?php else: ?><p><strong><?= $job['cost_finalized_at'] === null ? 'Recorded invoiced work cost so far' : 'Final recorded invoiced work cost' ?>: USD <?= esc($costs['invoiced']) ?></strong></p><?php endif; ?>
<p><?= $costs['payments'] === null ? 'No vendor payments recorded' : 'Recorded vendor payments: USD ' . esc($costs['payments']) ?></p>
<p>Payments and refunds are separate facts. Finalization confirms the recorded invoiced work cost as presently known.</p>
<?php if ($job['cost_finalized_at'] !== null): ?><p>Finalized <?= esc($job['cost_finalized_at']) ?> by operator <?= (int) $job['cost_finalized_by'] ?>.</p><p><?= nl2br(esc($job['cost_finalization_note'])) ?></p><?php endif; ?>
<?php foreach ($costs['issues'] as $issue): ?><p role="status"><?= esc($issue) ?></p><?php endforeach; ?>
<p><a href="<?= $base ?>/costs/new" class="button">Record invoice / credit / payment / refund</a></p>
<?php foreach (['Invoices / credits' => ['invoice', 'invoice_credit'], 'Payments / refunds' => ['payment', 'payment_refund']] as $heading => $kinds): ?>
<h3><?= esc($heading) ?></h3><ol class="damage-history">
<?php foreach ($costs['entries'] as $entry): if (! in_array($entry['kind_code'], $kinds, true)) { continue; } ?>
<li><strong><?= esc(\Config\VehicleDamageRepairCosts::KINDS[$entry['kind_code']]) ?> <?= (int) $entry['id'] ?></strong> &middot; <?= esc($entry['status_code']) ?><p>USD <?= esc($entry['amount']) ?> &middot; <?= esc($entry['occurred_on']) ?> &middot; <?= esc($entry['vendor_snapshot']) ?></p>
<?php if ($entry['vendor_reference'] !== null): ?><p>Vendor reference: <?= esc($entry['vendor_reference']) ?></p><?php endif; ?>
<?php if ($entry['related_cost_entry_id'] !== null): ?><p>Original related fact: <?= (int) $entry['related_cost_entry_id'] ?></p><?php endif; ?>
<?php if ($entry['replacement_of_cost_entry_id'] !== null): ?><p>Correction replaces fact <?= (int) $entry['replacement_of_cost_entry_id'] ?>. Original facts and references are retained.</p><?php endif; ?>
<?php if ($entry['note'] !== null): ?><p><?= nl2br(esc($entry['note'])) ?></p><?php endif; ?>
<p><a href="<?= $base ?>/documents/<?= (int) $entry['repair_document_id'] ?>/download">Supporting document <?= (int) $entry['repair_document_id'] ?></a></p>
<?php if ($entry['status_code'] === 'voided'): ?><p>Voided <?= esc($entry['voided_at']) ?> by operator <?= (int) $entry['voided_by'] ?>: <?= nl2br(esc($entry['void_reason'])) ?></p>
<?php elseif (isset($costs['entry_states'][$entry['id']])): ?><p><a href="<?= $base ?>/costs/<?= (int) $entry['id'] ?>/replacement">Correct this fact with a same-kind replacement</a></p>
<details class="capital-disclosure"><summary>Void this fact</summary><form action="<?= $base ?>/costs/<?= (int) $entry['id'] ?>/void" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'b23_void']) ?><input type="hidden" name="expected_entry_state" value="<?= esc($costs['entry_states'][$entry['id']], 'attr') ?>"><label>Correction reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="1" required> Void this recorded fact while retaining its evidence and history.</label><button type="submit">Void fact</button></form></details><?php endif; ?>
</li><?php endforeach; ?></ol><?php endforeach; ?>
<?php if ($job['cost_finalized_at'] === null && $costs['invoiced'] !== null && $costs['invoiced_state'] !== null): ?><details class="capital-disclosure"><summary>Finalize invoiced work cost</summary><form action="<?= $base ?>/costs/finalize" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'b23_finalize']) ?><input type="hidden" name="expected_invoiced_state" value="<?= esc($costs['invoiced_state'], 'attr') ?>"><p>Requires completed/cancelled work and retained performed-work history. Later invoice or credit changes, or reopening this order, invalidate finalization.</p><label>Finalization note<textarea name="note" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="1" required> All currently known invoice/credit facts have been recorded.</label><button type="submit">Finalize invoiced cost</button></form></details>
<?php elseif ($job['cost_finalized_at'] !== null && $costs['finalization_state'] !== null): ?><details class="capital-disclosure"><summary>Invalidate cost finalization</summary><form action="<?= $base ?>/costs/invalidate" method="post"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => 'b23_invalidate']) ?><input type="hidden" name="expected_finalization_state" value="<?= esc($costs['finalization_state'], 'attr') ?>"><label>Reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirmed" value="1" required> Clear finalization and preserve every monetary fact.</label><button type="submit">Invalidate finalization</button></form></details><?php endif; ?>
<?php endif; ?></section>
